def fill_solid_components(grid, min_size=5):
    """Fill the bounding box of every large connected component of one non-background color with that color; other non-background cells become the background."""
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    h,w=len(grid),len(grid[0])
    seen=[[False]*w for _ in range(h)]
    out=[row[:] for row in grid]
    def comp(i,j,c):
        cells=[]; q=deque([(i,j)]); seen[i][j]=True
        while q:
            a,b=q.popleft(); cells.append((a,b))
            for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                x,y=a+da,b+db
                if 0<=x<h and 0<=y<w and not seen[x][y] and grid[x][y]==c:
                    seen[x][y]=True; q.append((x,y))
        return cells
    for i in range(h):
        for j in range(w):
            if not seen[i][j] and grid[i][j]!=bg:
                c=grid[i][j]; cells=comp(i,j,c)
                if len(cells)>=min_size:
                    rs=[a for a,_ in cells]; cs=[b for _,b in cells]
                    for a in range(min(rs),max(rs)+1):
                        for b in range(min(cs),max(cs)+1):
                            out[a][b]=c
                else:
                    for a,b in cells: out[a][b]=bg
    return out

